<?php defined('BASEPATH') or exit('No direct script access allowed'); ?>
<div class="card">
    <div class="card-header border-bottom border-dashed"><h4 class="header-title mb-1">Pindah Kelas</h4><small class="text-muted">Pilihan kelas terhubung langsung ke Kelas Setting, termasuk tahun ajaran dan semester.</small></div>
    <div class="card-body">
        <div class="row g-3 align-items-end mb-4">
            <div class="col-lg-5"><label class="form-label" for="sourceClass">Kelas Sumber</label><select class="form-select" id="sourceClass"><option value="">Pilih kelas sumber</option><?php foreach ($kelas_setting as $row): ?><option value="<?= (int) $row['id'] ?>" data-grade-six="<?= preg_match('/^6(?:\D|$)/i', trim((string) $row['nama_kelas'])) ? '1' : '0' ?>"><?= html_escape($row['nama_kelas'].' · '.$row['periode'].' · '.$row['semester'].($row['wali_kelas'] ? ' · '.$row['wali_kelas'] : '')) ?></option><?php endforeach; ?></select></div>
            <div class="col-lg-5"><label class="form-label" for="targetClass">Kelas Tujuan</label><select class="form-select" id="targetClass"><option value="">Pilih kelas tujuan</option><option value="LULUS_<?= (int) $tahun_lulus ?>" id="graduateTarget" disabled>🎓 Lulus Tahun <?= (int) $tahun_lulus ?></option><?php foreach ($kelas_setting as $row): ?><option value="<?= (int) $row['id'] ?>"><?= html_escape($row['nama_kelas'].' · '.$row['periode'].' · '.$row['semester'].($row['wali_kelas'] ? ' · '.$row['wali_kelas'] : '')) ?></option><?php endforeach; ?></select></div>
            <div class="col-lg-2"><button class="btn btn-outline-primary w-100" id="previewMove"><i class="ri-eye-line me-1"></i>Tampilkan</button></div>
        </div>
        <div class="alert alert-info py-2" id="classLinkInfo">Pilih kelas berdasarkan Kelas Setting. Tidak perlu memilih tahun ajaran secara terpisah.</div>
        <div class="alert alert-warning py-2 d-none" id="graduationHint">Kelas sumber adalah kelas 6. Pilih <strong>Lulus Tahun <?= (int) $tahun_lulus ?></strong> untuk memindahkan siswa terpilih ke data Alumni tahun berjalan.</div>
        <div class="row g-4">
            <div class="col-lg-5"><div class="d-flex justify-content-between align-items-center mb-2"><div><h5 class="mb-0" id="sourceTitle">Siswa Kelas Sumber</h5><small class="text-muted" id="sourceInfo"></small></div><div class="form-check"><input class="form-check-input" type="checkbox" id="selectAllSource"><label class="form-check-label" for="selectAllSource">Pilih semua</label></div></div><div id="sourceRows" class="sdk-record-list"><div class="sdk-record-empty">Pilih kelas sumber lalu klik Tampilkan.</div></div></div>
            <div class="col-lg-2 d-flex align-items-center justify-content-center"><button class="btn btn-primary" id="processMove" disabled><span id="processMoveLabel">Pindahkan</span><i class="ri-arrow-right-line ms-1"></i></button></div>
            <div class="col-lg-5"><div class="mb-2"><h5 class="mb-0" id="targetTitle">Kelas Tujuan</h5><small class="text-muted" id="targetInfo"></small></div><div id="targetRows" class="sdk-record-list"><div class="sdk-record-empty">Pilih kelas tujuan untuk melihat data.</div></div></div>
        </div>
    </div>
</div>
<script>
$(function(){
    const base=<?=json_encode(base_url('admin/kurikulum/pindah_kelas/'),JSON_UNESCAPED_SLASHES)?>,csrf=<?=json_encode($csrf_token)?>,year=<?=(int)$tahun_lulus?>;
    const escapeHtml=value=>$('<div>').text(value==null||value===''?'-':value).html(),fail=xhr=>Swal.fire({icon:'error',title:'Gagal',text:(xhr.responseJSON||{}).message||'Proses tidak dapat diselesaikan.'});
    $('#sourceClass,#targetClass').select2({width:'100%',placeholder:'Pilih dari Kelas Setting'});
    function selectedSourceCanGraduate(){return String($('#sourceClass option:selected').data('grade-six'))==='1';}
    function updateGraduationOption(){const source=$('#sourceClass').val(),canGraduate=selectedSourceCanGraduate(),$target=$('#targetClass');$target.find('option').each(function(){const value=String(this.value);if(/^\d+$/.test(value))$(this).prop('disabled',value===String(source));});$('#graduateTarget').prop('disabled',!canGraduate);if(canGraduate&&!$target.val())$target.val('LULUS_'+year);if(!canGraduate&&$target.val()==='LULUS_'+year)$target.val('');if($target.val()===String(source))$target.val(canGraduate?'LULUS_'+year:'');$('#graduationHint').toggleClass('d-none',!canGraduate);$target.trigger('change.select2');}
    function studentCard(row,index,selectable){return `<div class="sdk-record-card"><div class="sdk-record-head"><span>NIS: <strong>${escapeHtml(row.nis)}</strong>${row.nisn?` · NISN: ${escapeHtml(row.nisn)}`:''}</span>${selectable?`<input class="form-check-input move-student" type="checkbox" value="${row.id}" aria-label="Pilih ${escapeHtml(row.nama_siswa)}">`:''}</div><div class="sdk-record-main"><div class="flex-grow-1"><h6 class="sdk-record-title">${index+1}. ${escapeHtml(row.nama_siswa)}</h6><div class="sdk-record-meta"><span>Jenis Kelamin: <strong>${escapeHtml(row.jk)}</strong></span></div></div></div></div>`;}
    function loadPreview(){const source=$('#sourceClass').val(),target=$('#targetClass').val();if(!source)return Swal.fire('Kelas sumber belum dipilih','Pilih kelas sumber dari Kelas Setting.','warning');$('#sourceRows,#targetRows').html('<div class="sdk-record-empty">Memuat data...</div>');$.post(base+'pindah_kelas_result',{id_kelas_sumber:source,tujuan:target},null,'json').done(response=>{const data=response.data||{},sourceRows=data.source_rows||[],targetRows=data.destination_rows||[],graduating=target==='LULUS_'+year;$('#sourceTitle').text(data.source?'Kelas '+data.source.nama_kelas:'Siswa Kelas Sumber');$('#sourceInfo').text(data.source?`${data.source.periode} · ${data.source.semester}`:'');$('#targetTitle').text(graduating?'Alumni Tahun '+year:(data.destination?'Kelas '+data.destination.nama_kelas:'Kelas Tujuan'));$('#targetInfo').text(data.destination?`${data.destination.periode} · ${data.destination.semester}`:'');$('#sourceRows').html(sourceRows.map((row,index)=>studentCard(row,index,true)).join('')||'<div class="sdk-record-empty">Tidak ada siswa aktif pada kelas sumber.</div>');$('#targetRows').html(targetRows.map((row,index)=>studentCard(row,index,false)).join('')||`<div class="sdk-record-empty">${graduating?'Belum ada alumni tahun '+year+'.':'Tidak ada siswa aktif pada kelas tujuan.'}</div>`);$('#sourceInfo').append(` · ${sourceRows.length} siswa`);$('#targetInfo').append(data.destination?` · ${targetRows.length} siswa`:'');$('#selectAllSource').prop('checked',false);$('#processMove').prop('disabled',!target||!sourceRows.length);$('#processMoveLabel').text(graduating?'Luluskan':'Pindahkan');}).fail(fail);}
    $('#sourceClass').on('change',updateGraduationOption);$('#previewMove').on('click',loadPreview);$('#selectAllSource').on('change',function(){$('.move-student').prop('checked',this.checked);});
    $('#sourceRows').on('change','.move-student',function(){const all=$('.move-student').length,checked=$('.move-student:checked').length;$('#selectAllSource').prop('checked',all>0&&all===checked);});
    $('#processMove').on('click',function(){const ids=$('.move-student:checked').map(function(){return this.value;}).get(),source=$('#sourceClass').val(),target=$('#targetClass').val(),graduating=target==='LULUS_'+year;if(!ids.length)return Swal.fire('Siswa belum dipilih','Pilih minimal satu siswa dari kelas sumber.','warning');if(!target)return Swal.fire('Tujuan belum dipilih','Pilih kelas tujuan atau kelulusan.','warning');Swal.fire({title:graduating?`Luluskan ${ids.length} siswa?`:`Pindahkan ${ids.length} siswa?`,text:graduating?`Siswa akan menjadi Alumni tahun ${year}.`:'Riwayat kelas lama tetap tersimpan.',icon:'question',showCancelButton:true,confirmButtonText:graduating?'Luluskan':'Pindahkan'}).then(result=>{if(!result.isConfirmed)return;const button=this;button.disabled=true;$.ajax({url:base+'proses',type:'POST',dataType:'json',data:{id_kelas_sumber:source,tujuan:target,id_siswa:ids,web_csrf_token:csrf}}).done(response=>{Swal.fire('Berhasil',response.message,'success');loadPreview();}).fail(fail).always(()=>button.disabled=false);});});
    updateGraduationOption();
});
</script>
